                    print(f"      Radius: {geom.Radius}")
                if hasattr(geom, 'Position'):
                    print(f"      Position: {geom.Position}")
                if hasattr(geom, 'XAxis'):
                    print(f"      XAxis: {geom.XAxis}")
                if hasattr(geom, 'YAxis'):
                    print(f"      YAxis: {geom.YAxis}")

                # For circle arcs
                if hasattr(geom, 'Arc'):
                    print(f"      Arc info available")

# List all features in Body
body = None
for obj in doc.Objects:
    if obj.TypeId == "PartDesign::Body":
        body = obj
        break

if body:
    print(f"\nBody features:")
    for feat in body.getObjectsInContainer():
        print(f"  - {feat.Name}: {feat.TypeId}")

FreeCAD.close(doc.Name)
